INSERT INTO "public"."team" ("id", "name", "trait", "best_member", "emblem") VALUES (1, 'T1', '첨단 기술과 세련된 도시 이미지를 강조하며, 철갑을 두른 기사를 마스코트로 사용합니다.', '{"batting":[5,13,4,16,2,3,9,12,19],"defense":{"C":5,"P":11,"1B":13,"2B":3,"3B":4,"CF":2,"DH":16,"LF":12,"RF":19,"SS":9,"BENCH":[0,6,10,8,1,7,14,15,17,18]}}', 'https://fnmhgdqvpnpyrcasnnvv.supabase.co/storage/v1/object/public/emblem/T1LOGo.svg'), (2, 'Dplus Kia', '거친 파도를 뚫고 나가는 역동적인 에너지를 상징하며, 강력한 공격력을 지향하는 팀 컬러를 가집니다.', null, 'https://fnmhgdqvpnpyrcasnnvv.supabase.co/storage/v1/object/public/emblem/Dplus_Kia_Teamlogo.svg'), (3, 'Gen.G', '뜨거운 열기와 산업 도시의 끈기를 상징하며, 단단한 수비와 조직력을 바탕으로 하는 팀입니다.', '{"batting":[null,null,null,null,null,null,null,null,null],"defense":{"C":47,"P":56,"1B":58,"2B":48,"3B":43,"CF":51,"DH":42,"LF":52,"RF":49,"SS":53,"BENCH":[54,55,59,44,57,50,40]}}', 'https://fnmhgdqvpnpyrcasnnvv.supabase.co/storage/v1/object/public/emblem/GenG_Team.svg'), (4, 'KIWOOM DRX', '천혜의 자연환경과 비상하는 날개를 상징하며, 빠르고 재치 있는 주루 플레이를 선호하는 팀입니다.', '{"batting":[60,63,64,66,67,71,69,70,68],"defense":{"C":64,"P":65,"1B":63,"2B":60,"3B":66,"CF":69,"DH":71,"LF":68,"RF":70,"SS":67,"BENCH":[61,72,73,62,74,75,76,77,78,79]}}', 'https://fnmhgdqvpnpyrcasnnvv.supabase.co/storage/v1/object/public/emblem/KiwoomDRX.svg');